package kr.workbench;

import burp.api.montoya.http.message.requests.HttpRequest;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.Instant;
import java.util.*;

/** Explicit account identity and manual work completion. Credentials and bindings never leave memory. */
final class AssessmentTracker {
 static final int ACCOUNT_LIMIT=16,OPERATION_LIMIT=10000,TASK_LIMIT=1000,EVENT_LIMIT=5000,INPUT_LIMIT=50000;
 record AccountInput(String label,String origin,String role,String tenant,boolean anonymous){}
 record Account(String id,String label,String origin,String role,String tenant,boolean anonymous){public String toString(){return label+(anonymous?" · 비로그인":"");}}
 record Binding(String account,String origin,Map<String,String> headers,Set<String> names,Set<String> cookies){Binding{headers=Map.copyOf(headers);names=Set.copyOf(names);cookies=Set.copyOf(cookies);}}
 record Session(String account,String origin,Set<String> names,Set<String> cookies,String fingerprint){}
 record Event(String time,String account,String target,String action,String detail){}
 record OperationView(String account,String method,String url,String state,long observed,long inspections,long evidence,String result,String review,String completedAt,String last,List<ActivityTracker.ParameterView> parameters){}
 record TaskView(String id,String title,String note,int endpoints,int accounts,int required,int inspected,int completed,int evidence,String state,String last,boolean requiresEvidence){}
 record EvidenceLink(String id,String filename,String time,Set<String> operations){}
 static final class Operation {
  final String account,method,url;final LinkedHashMap<String,Boolean> inputs=new LinkedHashMap<>();final Set<String> evidence=new LinkedHashSet<>();long observed,inspections;boolean completed;String review="",result="",completedAt="",last=now();
  Operation(String account,String method,String url){this.account=account;this.method=method;this.url=url;}
  String state(){return !review.isEmpty()?"재검토 필요":completed?"점검 완료":inspections>0?"검사 결과 있음":observed>0?"요청 관측":"미점검";}
 }
 static final class Task {
  final String id;String title,note,last=now(),review="";boolean completed,requiresEvidence;final Set<String> accounts=new LinkedHashSet<>(),endpoints=new LinkedHashSet<>();
  Task(String id,String title,String note){this.id=id;this.title=title;this.note=note;}
 }
 final LinkedHashMap<String,Account> accounts=new LinkedHashMap<>();final LinkedHashMap<String,Operation> operations=new LinkedHashMap<>();final LinkedHashMap<String,Task> tasks=new LinkedHashMap<>();final LinkedHashMap<String,EvidenceLink> artifacts=new LinkedHashMap<>();final ArrayDeque<Event> events=new ArrayDeque<>();
 private final List<Session> bindings=new ArrayList<>();private byte[] salt=new byte[32];long revision,rejected;int inputCount;
 AssessmentTracker(){new SecureRandom().nextBytes(salt);}
 static String now(){return Instant.now().toString();}
 static String origin(String raw){String safe=ActivityTracker.safeUrl(raw);if(safe==null)throw new IllegalArgumentException("HTTP(S) Origin이 필요합니다.");URI u=URI.create(safe);return u.getScheme()+"://"+u.getRawAuthority();}
 static String text(String value,int max){if(value==null||value.length()>max||value.chars().anyMatch(c->c<32&&c!='\n'&&c!='\t'))throw new IllegalArgumentException("점검 메타데이터 길이/문자 오류");return value.strip();}
 static String endpoint(String method,String url){String safe=ActivityTracker.safeUrl(url);if(safe==null||method==null||!method.matches("[A-Z]{1,24}"))throw new IllegalArgumentException("확정된 메서드/URL을 선택하세요.");return method+" "+safe;}
 static String opKey(String account,String method,String url){return account+" "+endpoint(method,url);}
 synchronized String register(AccountInput input){String label=text(input.label,64),base=origin(input.origin),role=text(input.role,64),tenant=text(input.tenant,64);if(label.isEmpty())throw new IllegalArgumentException("점검 계정 이름을 입력하세요.");if(accounts.size()>=ACCOUNT_LIMIT)throw new IllegalArgumentException("점검 계정 최대 16개");if(accounts.values().stream().anyMatch(a->a.label.equals(label)&&a.origin.equals(base)))throw new IllegalArgumentException("동일 Origin/계정 이름이 있습니다. 기존 계정을 선택하거나 다른 이름을 쓰세요.");String id=UUID.randomUUID().toString();accounts.put(id,new Account(id,label,base,role,tenant,input.anonymous));event(id,"","계정 등록",label);return id;}
 synchronized void editAccount(String id,String label,String role,String tenant){Account old=account(id);label=text(label,64);role=text(role,64);tenant=text(tenant,64);if(label.isEmpty())throw new IllegalArgumentException("점검 계정 이름을 입력하세요.");for(Account a:accounts.values())if(!a.id.equals(id)&&a.origin.equals(old.origin)&&a.label.equals(label))throw new IllegalArgumentException("동일 Origin/계정 이름 중복");accounts.put(id,new Account(id,label,old.origin,role,tenant,old.anonymous));event(id,"","계정 이름/역할 변경",old.label+" → "+label);}
 synchronized List<Account> accounts(){return List.copyOf(accounts.values());}
 synchronized Account account(String id){Account a=accounts.get(id);if(a==null)throw new IllegalArgumentException("등록된 점검 계정을 선택하세요.");return a;}
 private String fingerprint(Map<String,String> headers,Set<String> names,Set<String> cookies){List<String> values=new ArrayList<>();headers.forEach((name,value)->{String n=name.toLowerCase(Locale.ROOT);if(!names.contains(n)||AuthComparePanel.CSRF.contains(n)||value.isBlank())return;if(n.equals("cookie")){List<String> pairs=new ArrayList<>();for(String part:value.split(";")){int i=part.indexOf('=');if(i>0&&(cookies.isEmpty()||cookies.contains(part.substring(0,i).strip())))pairs.add(part.strip());}Collections.sort(pairs);if(!pairs.isEmpty())values.add(n+":"+String.join("; ",pairs));}else values.add(n+":"+value);});if(values.isEmpty())return "anonymous";Collections.sort(values);try{MessageDigest md=MessageDigest.getInstance("SHA-256");md.update(salt);for(String value:values){byte[] b=value.getBytes(StandardCharsets.UTF_8);md.update(Integer.toString(b.length).getBytes(StandardCharsets.UTF_8));md.update((byte)':');md.update(b);}return HexFormat.of().formatHex(md.digest());}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 static Map<String,String> headers(HttpRequest q){Map<String,String> out=new LinkedHashMap<>();for(var h:q.headers()){String n=h.name().toLowerCase(Locale.ROOT);out.merge(n,h.value(),(a,b)->a+(n.equals("cookie")?"; ":"\n")+b);}return out;}
 synchronized void bind(List<Binding> requested){List<Session> prepared=new ArrayList<>();for(Binding b:requested){Account a=account(b.account);String base=origin(b.origin);if(!a.origin.equals(base))throw new IllegalArgumentException("점검 계정 Origin과 요청이 다릅니다.");String fp=fingerprint(b.headers,b.names,b.cookies);if(a.anonymous!=fp.equals("anonymous"))throw new IllegalArgumentException("비로그인/인증 계정 유형과 선택 세션이 다릅니다.");Session next=new Session(a.id,base,b.names,b.cookies,fp);for(Session old:bindings)if(sameBinding(old,next)&&!old.account.equals(next.account))throw new IllegalArgumentException("같은 인증 조건이 다른 점검 계정에 연결되어 있습니다. 기존 세션 연결을 먼저 해제하세요.");for(Session old:prepared)if(sameBinding(old,next)&&!old.account.equals(next.account))throw new IllegalArgumentException("동일 세션을 서로 다른 계정에 지정할 수 없습니다.");prepared.add(next);}if(bindings.size()+prepared.stream().distinct().filter(s->!bindings.contains(s)).count()>512)throw new IllegalArgumentException("세션 연결 최대 512개 · 오래된 계정 세션 연결을 해제하세요.");for(Session s:prepared)if(!bindings.contains(s))bindings.add(s);revision++;}
 private boolean sameBinding(Session a,Session b){return a.origin.equals(b.origin)&&a.names.equals(b.names)&&a.cookies.equals(b.cookies)&&a.fingerprint.equals(b.fingerprint);}
 synchronized void unbind(String id){account(id);bindings.removeIf(s->s.account.equals(id));event(id,"","세션 연결 해제","점검 이력은 유지");}
 synchronized String match(HttpRequest q){if(q==null)return "";String base;try{base=origin(q.url());}catch(Exception e){return "";}Map<String,String> headers=headers(q);Set<String> matches=new HashSet<>();for(Session s:bindings)if(s.origin.equals(base)&&s.fingerprint.equals(fingerprint(headers,s.names,s.cookies)))matches.add(s.account);return matches.size()==1?matches.iterator().next():"";}
 private Operation operation(String id,String method,String url){Account a=account(id);String safe=ActivityTracker.safeUrl(url);String key=opKey(id,method,url);if(!a.origin.equals(origin(safe)))throw new IllegalArgumentException("점검 계정 Origin과 대상이 다릅니다.");Operation op=operations.get(key);if(op==null){if(operations.size()>=OPERATION_LIMIT){rejected++;throw new IllegalArgumentException("계정별 작업 기록 최대 10,000개");}op=new Operation(id,method,safe);operations.put(key,op);}return op;}
 private void reopenTasks(Operation op,String reason){String ep=endpoint(op.method,op.url);for(Task t:tasks.values())if(t.completed&&t.accounts.contains(op.account)&&t.endpoints.contains(ep)&&t.review.isEmpty()){t.review=reason;t.last=now();event(op.account,t.id,"업무 재검토",reason);}}
 private void inputs(Operation op,Collection<String> names){for(String name:names){if(name==null||name.length()>512||op.inputs.containsKey(name))continue;if(op.inputs.size()>=200||inputCount>=INPUT_LIMIT){rejected++;continue;}op.inputs.put(name,false);inputCount++;if(op.completed){op.review="완료 후 새 입력 발견 · "+name;reopenTasks(op,op.review);event(op.account,endpoint(op.method,op.url),"새 입력",name);}}}
 synchronized void observed(String id,String method,String url,Collection<String> names,String source){Operation op=operation(id,method,url);inputs(op,names);op.observed++;op.last=now();revision++;}
 synchronized void discovered(String method,String url,Collection<String> names){String safe=ActivityTracker.safeUrl(url);if(safe==null)return;for(Operation op:operations.values())if(op.method.equals(method)&&op.url.equals(safe))inputs(op,names);revision++;}
 synchronized void inspected(String id,String method,String url,Collection<String> names,String result,boolean review){Operation op=operation(id,method,url);inputs(op,names);op.inspections++;op.result=text(result,512);op.last=now();if(review){op.review=op.result;reopenTasks(op,op.review);}event(id,endpoint(method,url),"검사 결과",op.result);}
 synchronized void complete(String id,String method,String url,Collection<String> names,boolean value){Operation op=operation(id,method,url);inputs(op,names);if(!value&&op.completed)reopenTasks(op,"요구 계정의 URL 완료 해제");op.completed=value;op.completedAt=value?now():"";if(value)op.review="";op.last=now();event(id,endpoint(method,url),value?"수동 완료":"완료 해제","URL 완료와 입력별 완료는 별도 기록");}
 synchronized void completeInput(String id,String method,String url,String name,boolean value){Operation op=operation(id,method,url);if(!op.inputs.containsKey(name))throw new IllegalArgumentException("입력 이름을 선택하세요.");op.inputs.put(name,value);event(id,endpoint(method,url),value?"입력 수동 완료":"입력 완료 해제",name);}
 synchronized OperationView view(String id,String method,String url,Collection<String> known){account(id);Operation op=operations.get(opKey(id,method,url));LinkedHashMap<String,Boolean> params=new LinkedHashMap<>();for(String name:known)params.put(name,false);if(op!=null)params.putAll(op.inputs);return new OperationView(id,method,ActivityTracker.safeUrl(url),op==null?"미점검":op.state(),op==null?0:op.observed,op==null?0:op.inspections,op==null?0:op.evidence.size(),op==null?"":op.result,op==null?"":op.review,op==null?"":op.completedAt,op==null?"":op.last,params.entrySet().stream().map(p->new ActivityTracker.ParameterView(p.getKey(),p.getValue()?"점검 완료":"미점검")).toList());}
 synchronized String createTask(String title,String note,Set<String> required,boolean evidence){if(tasks.size()>=TASK_LIMIT)throw new IllegalArgumentException("업무 최대 1,000개");String id=UUID.randomUUID().toString();Task task=new Task(id,"","");updateTask(task,title,note,required,evidence);tasks.put(id,task);event("",id,"업무 등록",task.title);return id;}
 private void updateTask(Task task,String title,String note,Set<String> required,boolean evidence){title=text(title,120);note=text(note,1024);if(title.isEmpty()||required.isEmpty()||required.size()>ACCOUNT_LIMIT)throw new IllegalArgumentException("업무 이름과 요구 계정을 지정하세요.");for(String id:required)account(id);for(String ep:task.endpoints)if(required.stream().noneMatch(id->accounts.get(id).origin.equals(origin(ep.substring(ep.indexOf(' ')+1)))))throw new IllegalArgumentException("기존 대상의 Origin에 맞는 요구 계정이 필요합니다.");if(task.completed){task.completed=false;task.review="완료 후 업무 요구 조건 변경";}task.title=title;task.note=note;task.accounts.clear();task.accounts.addAll(required);task.requiresEvidence=evidence;task.last=now();}
 synchronized void editTask(String id,String title,String note,Set<String> required,boolean evidence){Task task=task(id);updateTask(task,title,note,required,evidence);event("",id,"업무 설정 변경",task.title);}
 private Task task(String id){Task t=tasks.get(id);if(t==null)throw new IllegalArgumentException("업무를 선택하세요.");return t;}
 synchronized void addTarget(String id,String method,String url){Task task=task(id);String ep=endpoint(method,url);if(task.accounts.stream().noneMatch(a->accounts.get(a).origin.equals(origin(url))))throw new IllegalArgumentException("대상 Origin에 맞는 요구 계정이 없습니다.");if(task.endpoints.contains(ep))return;if(task.endpoints.size()>=32)throw new IllegalArgumentException("업무당 대상 최대 32개");task.endpoints.add(ep);if(task.completed){task.completed=false;task.review="완료 후 새 대상 추가";}task.last=now();event("",id,"업무 대상 추가",ep);}
 synchronized void removeTarget(String id,String method,String url){Task task=task(id);if(task.endpoints.remove(endpoint(method,url))){task.completed=false;task.review="업무 대상 제외 · 요구 범위 재확인";task.last=now();event("",id,"업무 대상 제외",endpoint(method,url));}}
 synchronized List<OperationView> taskOperations(String id){Task t=task(id);List<OperationView> out=new ArrayList<>();for(String ep:t.endpoints){int n=ep.indexOf(' ');String method=ep.substring(0,n),url=ep.substring(n+1);for(String a:t.accounts)if(accounts.get(a).origin.equals(origin(url)))out.add(view(a,method,url,List.of()));}return List.copyOf(out);}
 private TaskView taskView(Task t){List<OperationView> pairs=taskOperations(t.id);int inspected=(int)pairs.stream().filter(v->v.inspections>0).count(),completed=(int)pairs.stream().filter(v->v.state.equals("점검 완료")).count();Set<String> evidence=new HashSet<>();for(OperationView pair:pairs){Operation op=operations.get(opKey(pair.account,pair.method,pair.url));if(op!=null)evidence.addAll(op.evidence);}boolean review=!t.review.isEmpty()||t.completed&&(completed!=pairs.size()||t.requiresEvidence&&evidence.isEmpty())||pairs.stream().anyMatch(v->v.state.equals("재검토 필요"));String state=review?"재검토 필요":pairs.isEmpty()?"대상 미등록":t.completed?"업무 완료":completed==pairs.size()&&(!t.requiresEvidence||evidence.size()>0)?"완료 준비":inspected>0?"점검 중":"미점검";if(t.requiresEvidence&&evidence.isEmpty()&&completed==pairs.size()&&!pairs.isEmpty()&&!review)state="증거 저장 필요";return new TaskView(t.id,t.title,t.note,t.endpoints.size(),t.accounts.size(),pairs.size(),inspected,completed,evidence.size(),state,t.last,t.requiresEvidence);}
 synchronized List<TaskView> tasks(){return tasks.values().stream().map(this::taskView).toList();}
 synchronized Set<String> taskAccounts(String id){return Set.copyOf(task(id).accounts);}
 synchronized void completeTask(String id,boolean value){Task t=task(id);if(value){TaskView v=taskView(t);if(v.required==0||v.completed!=v.required||t.requiresEvidence&&v.evidence==0)throw new IllegalArgumentException("모든 요구 계정/대상을 수동 완료하고 필요한 증거를 저장하세요.");t.review="";}t.completed=value;t.last=now();event("",id,value?"업무 수동 완료":"업무 완료 해제",t.title);}
 synchronized void evidenceSaved(String id,String filename,List<BountyEvidence.Item> items){if(artifacts.containsKey(id))return;if(artifacts.size()>=1000)throw new IllegalArgumentException("증거 묶음 최대 1,000개");String file=text(filename,256);if(!id.matches("[A-Za-z0-9_-]{1,128}")||items.size()>32)throw new IllegalArgumentException("증거 ID/개수 오류");Set<String> planned=new LinkedHashSet<>();for(var item:items)if(!item.account().isEmpty()&&accounts.containsKey(item.account())&&accounts.get(item.account()).origin.equals(origin(item.url())))planned.add(opKey(item.account(),item.method(),item.url()));long additions=planned.stream().filter(key->!operations.containsKey(key)).count();if(operations.size()+additions>OPERATION_LIMIT)throw new IllegalArgumentException("계정별 작업 한도 초과 · 증거는 저장되었지만 현황 연결 불가");Set<String> refs=new LinkedHashSet<>();for(var item:items){if(item.account().isEmpty()||!accounts.containsKey(item.account()))continue;Account a=accounts.get(item.account());if(!a.origin.equals(origin(item.url())))continue;Operation op=operation(a.id,item.method(),item.url());op.evidence.add(id);op.last=now();refs.add(opKey(a.id,op.method,op.url));}if(refs.isEmpty())return;String time=now();artifacts.put(id,new EvidenceLink(id,file,time,Set.copyOf(refs)));event("",id,"증거 ZIP 저장",file);}
 synchronized List<Event> history(){return List.copyOf(events);}
 private void event(String account,String target,String action,String detail){if(events.size()>=EVENT_LIMIT)events.removeFirst();events.addLast(new Event(now(),account,target,action,detail.substring(0,Math.min(detail.length(),512))));revision++;}
 synchronized void clear(){accounts.clear();operations.clear();tasks.clear();artifacts.clear();events.clear();bindings.clear();new SecureRandom().nextBytes(salt);inputCount=0;rejected=0;revision++;}
 synchronized Map<String,Object> save(){List<Object> ops=new ArrayList<>();for(Operation op:operations.values()){Map<String,Object> row=new LinkedHashMap<>();row.put("account",op.account);row.put("method",op.method);row.put("url",op.url);row.put("observed",op.observed);row.put("inspections",op.inspections);row.put("completed",op.completed);row.put("completedAt",op.completedAt);row.put("last",op.last);row.put("review",op.review);row.put("result",op.result);row.put("inputs",op.inputs);row.put("evidence",op.evidence);ops.add(row);}List<Object> jobs=new ArrayList<>();for(Task t:tasks.values())jobs.add(Map.of("id",t.id,"title",t.title,"note",t.note,"accounts",t.accounts,"endpoints",t.endpoints,"completed",t.completed,"requiresEvidence",t.requiresEvidence,"review",t.review,"last",t.last));return Map.of("accounts",accounts.values().stream().map(a->Map.of("id",a.id,"label",a.label,"origin",a.origin,"role",a.role,"tenant",a.tenant,"anonymous",a.anonymous)).toList(),"operations",ops,"tasks",jobs,"artifacts",artifacts.values().stream().map(a->Map.of("id",a.id,"filename",a.filename,"time",a.time,"operations",a.operations)).toList(),"events",events.stream().map(e->Map.of("time",e.time,"account",e.account,"target",e.target,"action",e.action,"detail",e.detail)).toList());}
 private static String field(Map<?,?> m,String key,int max){return text(Objects.toString(m.get(key),""),max);}
 private static long count(Object value){return value instanceof Number n?Math.max(0,Math.min(1000000000L,n.longValue())):0;}
 private static List<?> rows(Map<?,?> m,String key,int limit){Object value=m.get(key);if(!(value instanceof List<?> list)||list.size()>limit)throw new IllegalArgumentException("점검 기록 목록/한도 오류 · "+key);return list;}
 private static String id(Map<?,?> m,String key){String id=field(m,key,64);if(!id.matches("[A-Za-z0-9_-]{1,64}"))throw new IllegalArgumentException("점검 기록 ID 오류");return id;}
 synchronized void load(Object value){if(!(value instanceof Map<?,?> doc))throw new IllegalArgumentException("계정/업무 기록 형식 오류");AssessmentTracker imported=new AssessmentTracker();for(Object obj:rows(doc,"accounts",ACCOUNT_LIMIT)){if(!(obj instanceof Map<?,?> row))throw new IllegalArgumentException("계정 기록 오류");String id=id(row,"id"),label=field(row,"label",64),base=origin(field(row,"origin",8192));if(label.isEmpty()||imported.accounts.containsKey(id))throw new IllegalArgumentException("계정 ID/이름 오류");imported.accounts.put(id,new Account(id,label,base,field(row,"role",64),field(row,"tenant",64),Boolean.TRUE.equals(row.get("anonymous"))));}
  for(Object obj:rows(doc,"operations",OPERATION_LIMIT)){if(!(obj instanceof Map<?,?> row))throw new IllegalArgumentException("계정별 대상 기록 오류");String a=id(row,"account"),method=field(row,"method",24),url=field(row,"url",8192);String key=opKey(a,method,url);if(imported.operations.containsKey(key))throw new IllegalArgumentException("중복 계정별 대상");Operation op=imported.operation(a,method,url);op.observed=count(row.get("observed"));op.inspections=count(row.get("inspections"));op.completed=Boolean.TRUE.equals(row.get("completed"));op.completedAt=field(row,"completedAt",64);op.last=field(row,"last",64);op.review=field(row,"review",512);op.result=field(row,"result",512);if(!(row.get("inputs") instanceof Map<?,?> inputs)||inputs.size()>200)throw new IllegalArgumentException("입력 목록 오류");for(var entry:inputs.entrySet()){String name=text(entry.getKey().toString(),512);if(imported.inputCount>=INPUT_LIMIT)throw new IllegalArgumentException("점검 입력 한도 초과");op.inputs.put(name,Boolean.TRUE.equals(entry.getValue()));imported.inputCount++;}for(Object item:rows(row,"evidence",1000))op.evidence.add(text(item.toString(),128));}
  for(Object obj:rows(doc,"tasks",TASK_LIMIT)){if(!(obj instanceof Map<?,?> row))throw new IllegalArgumentException("업무 기록 오류");String id=id(row,"id");if(imported.tasks.containsKey(id))throw new IllegalArgumentException("중복 업무 ID");Set<String> required=new LinkedHashSet<>();for(Object a:rows(row,"accounts",ACCOUNT_LIMIT))required.add(a.toString());Task t=new Task(id,"","");imported.updateTask(t,field(row,"title",120),field(row,"note",1024),required,Boolean.TRUE.equals(row.get("requiresEvidence")));imported.tasks.put(id,t);for(Object ep:rows(row,"endpoints",32)){String target=ep.toString();int n=target.indexOf(' ');if(n<1)throw new IllegalArgumentException("업무 대상 오류");imported.addTarget(id,target.substring(0,n),target.substring(n+1));}t.completed=Boolean.TRUE.equals(row.get("completed"));t.review=field(row,"review",512);t.last=field(row,"last",64);}
  for(Object obj:rows(doc,"artifacts",1000)){if(!(obj instanceof Map<?,?> row))throw new IllegalArgumentException("증거 기록 오류");String id=field(row,"id",128);if(!id.matches("[A-Za-z0-9_-]{1,128}")||imported.artifacts.containsKey(id))throw new IllegalArgumentException("증거 ID 오류");Set<String> refs=new LinkedHashSet<>();for(Object ref:rows(row,"operations",32)){if(!imported.operations.containsKey(ref.toString()))throw new IllegalArgumentException("증거 대상 참조 오류");refs.add(ref.toString());}imported.artifacts.put(id,new EvidenceLink(id,field(row,"filename",256),field(row,"time",64),Set.copyOf(refs)));}for(Operation op:imported.operations.values())for(String e:op.evidence)if(!imported.artifacts.containsKey(e)||!imported.artifacts.get(e).operations.contains(opKey(op.account,op.method,op.url)))throw new IllegalArgumentException("계정별 증거 참조 오류");
  imported.events.clear();for(Object obj:rows(doc,"events",EVENT_LIMIT)){if(!(obj instanceof Map<?,?> row))throw new IllegalArgumentException("이력 기록 오류");String a=field(row,"account",64);if(!a.isEmpty()&&!imported.accounts.containsKey(a))throw new IllegalArgumentException("이력 계정 참조 오류");imported.events.add(new Event(field(row,"time",64),a,field(row,"target",8300),field(row,"action",64),field(row,"detail",512)));}replace(imported);
 }
 synchronized void replace(AssessmentTracker imported){accounts.clear();accounts.putAll(imported.accounts);operations.clear();operations.putAll(imported.operations);tasks.clear();tasks.putAll(imported.tasks);artifacts.clear();artifacts.putAll(imported.artifacts);events.clear();events.addAll(imported.events);bindings.clear();new SecureRandom().nextBytes(salt);inputCount=imported.inputCount;rejected=imported.rejected;revision++;}
 synchronized void appendWorkbook(LinkedHashMap<String,List<List<String>>> workbook,List<ActivityTracker.View> endpoints){List<List<String>> profileRows=new ArrayList<>(),opRows=new ArrayList<>(),taskRows=new ArrayList<>(),eventRows=new ArrayList<>();profileRows.add(List.of("계정 ID","이름","Origin","역할","조직","비로그인"));for(Account a:accounts.values())profileRows.add(List.of(a.id,a.label,a.origin,a.role,a.tenant,String.valueOf(a.anonymous)));opRows.add(List.of("계정","메서드","URL","상태","관측","검사","저장 증거","최근 결과","재검토","완료 시각"));for(Operation op:operations.values()){OperationView v=view(op.account,op.method,op.url,List.of());opRows.add(List.of(accounts.get(v.account).label,v.method,v.url,v.state,""+v.observed,""+v.inspections,""+v.evidence,v.result,v.review,v.completedAt));}taskRows.add(List.of("업무","대상 수","요구 계정 수","요구 조합","검사 조합","완료 조합","저장 증거","상태"));for(TaskView t:tasks())taskRows.add(List.of(t.title,""+t.endpoints,""+t.accounts,""+t.required,""+t.inspected,""+t.completed,""+t.evidence,t.state));eventRows.add(List.of("시각","계정","대상/업무 ID","작업","설명"));for(Event e:events)eventRows.add(List.of(e.time,e.account.isEmpty()?"":accounts.get(e.account).label,e.target,e.action,e.detail));workbook.put("점검 계정",profileRows);workbook.put("계정별 기록",opRows);workbook.put("업무별 현황",taskRows);workbook.put("점검 이력",eventRows);}
}
